['Generating {DURATION_HOURS}-hour fractal broadcast")\nprint(f"    Carrier: {CARRIER} Hz")\nprint(f"    Sample rate: {SAMPLE_RATE} Hz")\nprint(f"    Output: {OUTPUT_PATH}', 'Time array\nt = np.linspace(0, duration_sec, total_samples, endpoint=False)\n\n# Base carrier\ncarrier = np.sin(2 * np.pi * CARRIER * t)\n\n# Fractal envelope\nenv = np.zeros_like(t)\nrng = np.random.default_rng(seed=42)\nfor i in range(1, DEPTH + 1):\n    freq = CARRIER / (PHI ** i)\n    amp = 1.0 / (PHI ** (i * 0.5))\n    phase = rng.uniform(0, 2 * np.pi)\n    env += amp * np.sin(2 * np.pi * freq * t + phase)\nenv = env / np.max(np.abs(env))\n\n# Modulate\nwaveform = (carrier * env * 0.8).astype(np.float32)\nwaveform_int16 = (waveform * 32767).astype(np.int16)\n\n# Write WAV\nprint(', ['Writing WAV file...', "with wave.open(OUTPUT_PATH, 'w') as wf:\n    wf.setnchannels(1)\n    wf.setsampwidth(2)\n    wf.setframerate(SAMPLE_RATE)\n    wf.writeframes(waveform_int16.tobytes())\n\nsize_gb = os.path.getsize(OUTPUT_PATH) / (1024**3)\nprint(f", ['Done!")\nprint(f', ['File: {OUTPUT_PATH}")\nprint(f', ['Size: {size_gb:.2f} GB")\nprint(f', ['Duration: {DURATION_HOURS} hours")\nprint()\nprint("To import to Apple Music:")\nprint("1. Open Music app")\nprint("2. File → Add to Library → select the WAV file")\nprint("3. Create playlist \'Cathedral Fractal\' and add it")\nprint("4. Set playlist to loop']]]]]]